## 1. TRIGGER
Webhook POST /ugc-script-agent
Payload: { "client_code": "ABC-0213" }

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const client_code = (body.client_code || body.clientCode || '').trim();
if (!client_code) throw new Error('client_code is required');
return [{ json: { client_code } }];

// ============================================================
// Validate brief and build the master context object
// that all agents will reference throughout the pipeline.
// ============================================================

const items = $input.all();
if (!items || items.length === 0 || !items[0].json) {
  throw new Error('No client found. Check client_code in the Client Database.');
}
const row = items[0].json;
function c(v) { return v === undefined || v === null ? '' : String(v).trim(); }

const brief = {
  client_code: c(row.client_code),
  brand_name: c(row.brand_name),
  client_name: c(row.client_name),
  client_email: c(row.client_email),
  website_url: c(row.website_url),
  product_feature: c(row.product_feature),
  differentiator: c(row.differentiator),
  competitors: c(row.competitors),
  competitor_strengths: c(row.competitor_strengths),
  target_user: c(row.target_user),
  biggest_problem: c(row.biggest_problem),
  main_hesitation: c(row.main_hesitation),
  social_proof: c(row.social_proof),
  selling_proposition: c(row.selling_proposition),
  brand_personality: c(row.brand_personality),
  credibility_point: c(row.credibility_point),
  transformation: c(row.transformation),
  best_concepts: c(row.best_concepts),
  compliance: c(row.compliance),
  reference_ads: c(row.reference_ads),
  available_assets: c(row.available_assets),
  do_not_say: c(row.do_not_say),
  additional_notes: c(row.additional_notes),
  num_scripts: parseInt(c(row.num_scripts)) || 3
};

const required = ['brand_name', 'product_feature', 'target_user'];
const missing = required.filter(f => !brief[f]);
if (missing.length > 0) throw new Error('Brief missing: ' + missing.join(', '));

return [{ json: { brief, revision_count: 0 } }];

// ============================================================
// Build the Research Agent's input prompt from the brief.
// The agent will analyze this and produce research insights.
// ============================================================

const { brief } = $json;

const prompt = `DEEP RESEARCH MISSION for ${brief.brand_name}.

You have 5 research tools. USE ALL OF THEM to gather real intelligence.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Selling Proposition: ${brief.selling_proposition}
Website: ${brief.website_url}
Competitors: ${brief.competitors}
Competitor Strengths: ${brief.competitor_strengths}
Target User: ${brief.target_user}
Biggest Problem: ${brief.biggest_problem}
Main Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Brand Personality: ${brief.brand_personality}
Credibility: ${brief.credibility_point}
Social Proof: ${brief.social_proof}
Reference Ads: ${brief.reference_ads || 'Not specified'}

== YOUR RESEARCH TASKS (do ALL of these) ==

1. READ THE BRAND WEBSITE: Use read_website on ${brief.website_url || 'the brand website'} to understand their product, pricing, and claims.

2. MINE AMAZON/MARKETPLACE REVIEWS: Use amazon_review_search for "${brief.product_feature}" to find real customer language. Then use read_website on the top 2-3 review pages.

3. SEARCH REDDIT: Use reddit_search for "${brief.biggest_problem}" AND for "${brief.product_feature}". Extract real discussions, pain points, and the exact words people use.

4. RESEARCH COMPETITOR ADS: Use competitor_ad_search for each competitor: ${brief.competitors || 'the main competitors in this space'}. Find what ads they are running.

5. CHECK SOCIAL SENTIMENT: Use google_search for "${brief.brand_name} review" and "${brief.product_feature} TikTok". See what real people are saying.

6. MINE VIRAL CONCEPTS ACROSS ALL PLATFORMS (CRITICAL):
   a) TikTok: Use tiktok_viral_search for "${brief.product_feature}" and "${brief.biggest_problem}"
   b) Instagram: Use instagram_viral_search for "${brief.product_feature} Reel" and the product category
   c) Meta Ad Library: Use meta_ad_library_search for EACH competitor: ${brief.competitors || 'competitors in this space'} — find their ACTIVE paid ads
   d) Competitor ads: Use competitor_ad_search for general ad breakdowns
   Find 10-15 references total across platforms (mix organic + paid). For each, note URL, platform, format, hook, why it works, and how it adapts to ${brief.brand_name}.

== REQUIRED OUTPUT SECTIONS ==

1. BRAND ANALYSIS — What the brand website reveals about positioning, pricing, messaging.

2. VOICE OF CUSTOMER GOLDMINE (MOST IMPORTANT SECTION)
   Extract 10-15 real quotes from Amazon reviews, Reddit, and forums. Label each:
   - PAIN: exact customer complaints and frustrations
   - DESIRE: what they wish for / dream outcome
   - PROOF: specific results they mention (timeframes, metrics)
   - OBJECTION: hesitations and doubts they express
   - LANGUAGE: exact phrases and words they use repeatedly
   These raw quotes become hooks and scripts.

3. COMPETITOR AD LANDSCAPE — What are competitors doing? What angles are overused? Where is the white space?

4. AUDIENCE PSYCHOLOGY — How this audience talks, thinks, and makes purchase decisions based on real data (not assumptions).

5. MARKET GAP ANALYSIS — What is this brand's unfair advantage? What can they say that competitors can NOT?

6. SCRIPT AMMUNITION — 5-7 specific, actionable insights that should directly inform script angles. Examples:
   - "Amazon reviewers repeatedly mention 'visible results in 2 weeks' — use this exact timeframe in proof sections"
   - "Reddit users are skeptical of vitamin C serums because they oxidize — address this objection head-on"
   - "Competitors are all running testimonial-style ads — there's white space for myth-buster and comparison formats"

Do NOT skip the tool research. The entire value of this agent is real data, not AI assumptions.`;

return [{ json: { prompt, brief } }];

// ============================================================
// Build Strategy Agent prompt with brief + research output
// The strategist makes creative DECISIONS based on research.
// ============================================================

const brief = $('Validate Brief').first().json.brief;
const researchOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);

const numConcepts = Math.ceil(brief.num_scripts * 1.5);

const prompt = `You have deep research from our Research Analyst including VIRAL TIKTOK REFERENCE VIDEOS. Now develop the creative strategy.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}
Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Personality: ${brief.brand_personality}
Social Proof: ${brief.social_proof}
Credibility: ${brief.credibility_point}
Best Concepts: ${brief.best_concepts || 'Not specified'}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Scripts Ordered: ${brief.num_scripts}
Concepts to Present: ${numConcepts} (we ALWAYS overdeliver — present more concepts than ordered)

== RESEARCH REPORT (includes viral TikTok reference videos) ==
${researchOutput}

== YOUR TASK ==
Develop ${numConcepts} UNIQUE creative concepts (NOT ${brief.num_scripts} — we present MORE than ordered, client picks their favorites).

Each concept MUST be inspired by a real reference video or ad from the research — TikTok virals, Instagram Reels, Facebook Ad Library ads, competitor creatives. Do NOT create concepts from thin air — anchor each one to a PROVEN winning format.

For EACH concept, provide ALL of these:
1. CONCEPT NAME — A distinctive, memorable name (e.g., "The Skeptic Convert", "Morning Glow Routine", "The Honest Review")
2. REFERENCE VIDEO/AD — The URL that inspired this concept (TikTok, Instagram, Facebook Ad Library, etc.). State which PLATFORM it's from. Describe what happens in the reference and how we are adapting it for ${brief.brand_name}.
3. FRAMEWORK — Which scripting framework (PAS, BAB, AIDA, 4Ps, Feel-Felt-Found, SLAP, Star-Story-Solution, Curiosity Gap, Contrast Frame, Micro-Story, PASTOR, FAB) and WHY
4. HOOK TYPE — Which hook category (controversy, POV, calling-out, negative, authority, social-proof, curiosity-gap, story, fear/urgency, hot-take, whisper, text-first) and WHY
5. HOOK — The exact opening line (under 10 words)
6. FORMAT — Which UGC video format (talking-head, GRWM, before-after, unboxing, POV, day-in-life, storytime, routine, side-by-side, green-screen, stitch-style, transformation) and WHY — should match the reference video format
7. FUNNEL STAGE — TOF, MOF, or BOF and WHY
8. EMOTIONAL JOURNEY — Specific sequence (e.g., frustration → curiosity → relief → desire)
9. TARGET OBJECTION — Which SPECIFIC hesitation this concept kills
10. KEY PERSUASION — The core argument
11. PLATFORM — Primary platform (TikTok, Reels, Facebook)
12. VIRALITY SCORE — Rate 1-10 based on: hook strength (3pts), format trend (3pts), audience match (2pts), uniqueness (2pts). Explain the score.
13. A/B TEST PAIR — Which OTHER concept from this batch could be tested against this one (same message, different hook OR same hook, different format)
14. ONE-LINE PITCH — How you would describe this concept to the client in 1 sentence

DIVERSITY RULES (NON-NEGOTIABLE):
- Each concept MUST use a DIFFERENT framework + hook type combination
- At least 4 different UGC video formats across all concepts
- Mix funnel stages: at least 2 TOF, 1-2 MOF, 1-2 BOF
- Mix platforms: not all TikTok
- Mix emotional triggers: not all pain-based
- At least one concept under 20 seconds (SLAP/Micro-Story)
- At least one concept that handles the MAIN objection
- At least 2 concepts inspired by GRWM, routine, or day-in-life formats (these are high-performing organic styles)
- Include at least 1 A/B test pair (2 concepts with same message, different execution)

Output the concepts sorted by VIRALITY SCORE (highest first).`;

return [{ json: { prompt, brief } }];

// ============================================================
// Build Script Writer prompt with brief + strategy.
// If this is a REVISION pass, include QA feedback.
// ============================================================

const brief = $('Validate Brief').first().json.brief;
const strategyOutput = $('Creative Strategist Agent').first().json.output || $('Creative Strategist Agent').first().json.text || '';

// Check if this is a revision pass
let revisionNotes = '';
let isRevision = false;
try {
  const qaCheck = $('Check QA Verdict').first().json;
  if (qaCheck.revision_notes) {
    revisionNotes = qaCheck.revision_notes;
    isRevision = true;
  }
} catch(e) {
  // First pass, no revision notes
}

let prompt;
if (isRevision) {
  prompt = `REVISION REQUESTED — The QA agent has reviewed your scripts and sent them back.

== QA REVISION NOTES ==
${revisionNotes}

== ORIGINAL BRIEF ==
Brand: ${brief.brand_name} | Product: ${brief.product_feature}
Differentiator: ${brief.differentiator} | Target: ${brief.target_user}
Personality: ${brief.brand_personality}
Compliance: ${brief.compliance || 'None'} | Do NOT Say: ${brief.do_not_say || 'None'}

== CREATIVE STRATEGY ==
${strategyOutput}

Rewrite the scripts addressing ALL revision notes. Keep what worked. Fix what didn't.
Maintain the same JSON output format as before.`;
} else {
  const numConcepts = Math.ceil(brief.num_scripts * 1.5);
  prompt = `Write COMPLETE UGC scripts for ALL ${numConcepts} concepts from the strategy below.

IMPORTANT: The strategist has created ${numConcepts} concepts (more than the ${brief.num_scripts} ordered). Write FULL scripts for ALL of them. The client will pick their favorites from the full concept deck.

Each concept has a REFERENCE VIDEO — a real viral TikTok. Your script should capture the same energy, format, and pacing of that reference while adapting it to ${brief.brand_name}.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Selling Proposition: ${brief.selling_proposition}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}
Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Personality: ${brief.brand_personality}
Credibility: ${brief.credibility_point}
Social Proof: ${brief.social_proof}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Notes: ${brief.additional_notes || 'None'}

== CREATIVE STRATEGY + CONCEPT DECK FROM STRATEGIST ==
${strategyOutput}

== OUTPUT FORMAT ==
For EACH concept (all ${numConcepts}), output this JSON structure:
{
  "scripts": [
    {
      "script_number": 1,
      "concept_name": "from strategy",
      "reference_video_url": "URL of the reference video or ad (TikTok, Instagram, Facebook Ad Library, etc.)",
      "reference_platform": "TikTok / Instagram Reels / Facebook Ad / Instagram Ad / YouTube",
      "reference_type": "organic viral / paid ad / UGC ad / creator content",
      "reference_video_description": "1-2 sentence description of the reference and how this script adapts it",
      "virality_score": 8,
      "concept_pitch": "One-line pitch for the client",
      "framework_used": "PAS / BAB / AIDA / etc.",
      "hook_type": "controversy / POV / calling-out / etc.",
      "funnel_stage": "TOF / MOF / BOF",
      "format": "the UGC format",
      "platform": "TikTok / Reels / Facebook",
      "hook": "Exact opening words (0-3 sec) — must work as text on screen too",
      "hook_reinforcement": "Second line that keeps them watching (3-5 sec)",
      "problem": "Relate to viewer — use THEIR language (5-10 sec)",
      "solution": "Natural product discovery — NOT a pitch (10-18 sec)",
      "proof": "Specific proof points — numbers, timeframes, sensory details (18-25 sec)",
      "cta": "Curiosity-driven close — pull, don't push (25-30 sec)",
      "full_script": "The COMPLETE script as the creator would say it — include filler words, pauses [beat], reactions, natural speech patterns. This should read like a transcript of a real person talking, not a marketing document.",
      "visual_direction": "Second-by-second direction: 0-3s: [action], 3-8s: [action], 8-15s: [action], 15-25s: [action], 25-30s: [action]",
      "on_screen_text": ["Text that appears at 0-2 sec (hook)", "Text at 10-12 sec (key claim)", "Text at 25-28 sec (CTA)"],
      "creator_notes": "Tone (excited/calm/serious/playful), energy level (1-10), pacing (fast/medium/slow), setting (bathroom/kitchen/outdoors), wardrobe vibe, lighting",
      "estimated_duration": "25 sec",
      "thumbnail_frame": "Description of the first frame if this were a thumbnail — what would make someone tap?"
    }
  ]
}

CRITICAL: The 'full_script' field must sound like a REAL PERSON. Include:
- Filler words: 'like', 'honestly', 'okay so', 'literally'
- Reactions: 'wait', 'omg', 'no way'
- Pauses: [beat], [looks at camera], [shows product]
- Natural transitions: 'and the crazy thing is...', 'but here\'s what nobody tells you...'

If a script reads like it was written by AI, it has FAILED.

Output ONLY valid JSON.`;
}

return [{ json: { prompt, brief, is_revision: isRevision } }];

// ============================================================
// Build QA Agent prompt with scripts + compliance rules.
// The QA agent DECIDES: approve or send back for revision.
// ============================================================

const brief = $('Validate Brief').first().json.brief;
const writerOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const revisionCount = $('Validate Brief').first().json.revision_count || 0;

const prompt = `REVIEW THESE UGC SCRIPTS. You are the final quality gate.

== COMPLIANCE RULES (NON-NEGOTIABLE) ==
Compliance Policy: ${brief.compliance || 'No specific compliance rules'}
Do NOT Say (exact phrases AND close synonyms): ${brief.do_not_say || 'No restrictions'}

== BRAND CONTEXT ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Target: ${brief.target_user}
Brand Personality: ${brief.brand_personality}
Differentiator: ${brief.differentiator}
Main Hesitation: ${brief.main_hesitation}

== SCRIPTS TO REVIEW ==
${writerOutput}

== YOUR REVIEW CHECKLIST ==
For EACH script evaluate:

COMPLIANCE:
- Any exact or semantic 'do not say' violations?
- Any unsubstantiated medical/result claims?
- Use the compliance_check tool to scan programmatically.

FRAMEWORK EXECUTION:
- Is the stated framework (PAS/BAB/AIDA etc.) actually executed correctly?
- Does a PAS script AGITATE before solving? Does a BAB show real contrast?
- Is the hook type matching the category? (A 'controversy' hook must create tension)

PERFORMANCE PREDICTION:
- THUMB-STOP: Read only the hook. Score 1-10. Would a real person stop scrolling?
- AUTHENTICITY: Does full_script read like a real person or like ChatGPT? Look for filler words, natural speech.
- AD PACING: Does the product reveal happen between 8-18 seconds? Not too early (feels like ad), not too late (loses interest)?
- PROOF SPECIFICITY: Are proof points specific (numbers, time, names) or vague?
- CTA PULL: Does the CTA create curiosity or is it generic 'check it out'?

DIVERSITY:
- Are frameworks actually different across scripts? (not all PAS)
- Are hook types varied? (not all starting with questions)
- Are funnel stages mixed? (not all TOF)
- Would each script feel like a DIFFERENT creator made it?

Then make your DECISION. Output this JSON:
{
  "verdict": "APPROVED" or "NEEDS_REVISION",
  "overall_quality": 7.5,
  "revision_number": ${revisionCount},
  "script_reviews": [
    {
      "script_number": 1,
      "compliance_pass": true,
      "quality_score": 8,
      "issues": [],
      "revision_notes": ""
    }
  ],
  "batch_notes": "Overall assessment and specific revision instructions if needed"
}

RULES:
- If ANY script has a compliance violation → NEEDS_REVISION
- If average quality < 7 → NEEDS_REVISION
- If hooks are weak or generic → NEEDS_REVISION
- If scripts feel too similar → NEEDS_REVISION
- Be rigorous but fair. Don't reject for minor style preferences.
- This is revision #${revisionCount} of max 2. ${revisionCount >= 2 ? 'THIS IS THE FINAL REVIEW — approve with notes for manual editing if quality is acceptable.' : ''}

Output ONLY valid JSON.`;

return [{ json: { prompt, brief, writer_output: writerOutput, revision_count: revisionCount } }];

const input = JSON.parse($input.first().json.query || '{}');
const text = (input.script_text || '').toLowerCase();
const forbidden = (input.forbidden_phrases || '').split(',').map(p => p.trim().toLowerCase()).filter(Boolean);
const violations = forbidden.filter(phrase => text.includes(phrase));
return JSON.stringify({ violations, has_violations: violations.length > 0, checked_phrases: forbidden.length });

// ============================================================
// Check QA Verdict — The critical DECISION point.
// Parse the QA agent's output and determine next action.
// ============================================================

const qaOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const prevData = $('Build QA Prompt').first().json;
const writerOutput = prevData.writer_output;
let revisionCount = prevData.revision_count || 0;

// Parse QA JSON from agent output
let qaResult;
try {
  // Try direct parse
  qaResult = JSON.parse(qaOutput);
} catch(e) {
  // Try extracting JSON from text
  const match = qaOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try { qaResult = JSON.parse(match[0]); } catch(e2) {
      qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
    }
  } else {
    qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
  }
}

const verdict = (qaResult.verdict || 'APPROVED').toUpperCase();
const needsRevision = verdict === 'NEEDS_REVISION' && revisionCount < 2;

return [{
  json: {
    verdict,
    needs_revision: needsRevision,
    revision_count: revisionCount + (needsRevision ? 1 : 0),
    revision_notes: qaResult.batch_notes || '',
    script_reviews: qaResult.script_reviews || [],
    overall_quality: qaResult.overall_quality || 0,
    writer_output: writerOutput,
    qa_output: qaOutput
  }
}];

// ============================================================
// Route back to Script Writer with revision context.
// Updates the revision counter in the brief data.
// ============================================================

const brief = $('Validate Brief').first().json.brief;
const verdict = $input.first().json;

// Build revision prompt that goes back to writer
const prompt = verdict.revision_notes + '\n\nScript-level feedback:\n' + 
  (verdict.script_reviews || []).map(r => 
    `Script ${r.script_number}: Score ${r.quality_score}/10${r.issues && r.issues.length ? ' — Issues: ' + r.issues.join(', ') : ''}${r.revision_notes ? ' — Notes: ' + r.revision_notes : ''}`
  ).join('\n');

return [{ json: { prompt, brief, is_revision: true } }];

// ============================================================
// Format Approved Scripts for Output
// Parses the writer's output into structured script objects
// and formats them for Google Docs and ClickUp.
// ============================================================

const brief = $('Validate Brief').first().json.brief;
const verdictData = $input.first().json;
const writerOutput = verdictData.writer_output || '';
const qaQuality = verdictData.overall_quality || 'N/A';

// Parse scripts from writer output
let scripts = [];
try {
  const parsed = JSON.parse(writerOutput);
  scripts = parsed.scripts || [parsed];
} catch(e) {
  const match = writerOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      scripts = parsed.scripts || [parsed];
    } catch(e2) {
      scripts = [{ script_number: 1, full_script: writerOutput, angle_name: 'Script', format: 'UGC', hook: '', visual_direction: '', on_screen_text: [], creator_notes: '', estimated_duration: '30 sec' }];
    }
  }
}

// Format each script as a readable document for Google Docs
const formattedScripts = scripts.map((s, i) => {
  const num = s.script_number || (i + 1);
  const onScreenText = Array.isArray(s.on_screen_text)
    ? s.on_screen_text.map(t => `  - ${t}`).join('\n')
    : s.on_screen_text || '';

  const docContent = [
    `${brief.brand_name} | UGC Concept #${num}`,
    `${'='.repeat(50)}`,
    '',
    `CONCEPT: ${s.concept_name || s.angle_name || 'N/A'}`,
    `CONCEPT PITCH: ${s.concept_pitch || 'N/A'}`,
    `REFERENCE: ${s.reference_video_url || 'N/A'}`,
    `REF PLATFORM: ${s.reference_platform || 'N/A'} (${s.reference_type || 'N/A'})`,
    `REF DESCRIPTION: ${s.reference_video_description || 'N/A'}`,
    `VIRALITY SCORE: ${s.virality_score || 'N/A'}/10`,
    `FORMAT: ${s.format || 'N/A'}`,
    `DURATION: ${s.estimated_duration || '30 sec'}`,
    `QA SCORE: ${qaQuality}/10`,
    '',
    `${'─'.repeat(50)}`,
    'HOOK (0-3 sec)',
    `${'─'.repeat(50)}`,
    s.hook || '',
    '',
    `${'─'.repeat(50)}`,
    'PROBLEM (3-8 sec)',
    `${'─'.repeat(50)}`,
    s.problem || '',
    '',
    `${'─'.repeat(50)}`,
    'SOLUTION (8-18 sec)',
    `${'─'.repeat(50)}`,
    s.solution || '',
    '',
    `${'─'.repeat(50)}`,
    'PROOF (18-25 sec)',
    `${'─'.repeat(50)}`,
    s.proof || '',
    '',
    `${'─'.repeat(50)}`,
    'CTA (25-30 sec)',
    `${'─'.repeat(50)}`,
    s.cta || '',
    '',
    `${'='.repeat(50)}`,
    'FULL SCRIPT (for creator)',
    `${'='.repeat(50)}`,
    s.full_script || '',
    '',
    `${'='.repeat(50)}`,
    'VISUAL DIRECTION',
    `${'='.repeat(50)}`,
    s.visual_direction || '',
    '',
    'ON-SCREEN TEXT:',
    onScreenText,
    '',
    'CREATOR NOTES:',
    s.creator_notes || '',
    '',
    `${'─'.repeat(50)}`,
    `Generated by Smashed Agency Script Agent Team`,
    `Client: ${brief.client_code} | ${new Date().toISOString()}`
  ].join('\n');

  return {
    script_number: num,
    concept_name: s.concept_name || s.angle_name || 'Concept ' + num,
    reference_video_url: s.reference_video_url || '',
    reference_platform: s.reference_platform || '',
    reference_type: s.reference_type || '',
    reference_video_description: s.reference_video_description || '',
    virality_score: s.virality_score || 0,
    concept_pitch: s.concept_pitch || '',
    format: s.format || 'UGC',
    hook: s.hook || '',
    full_script: s.full_script || '',
    doc_content: docContent,
    estimated_duration: s.estimated_duration || '30 sec'
  };
});

return [{
  json: {
    brief,
    scripts: formattedScripts,
    total_scripts: formattedScripts.length,
    qa_quality: qaQuality,
    revisions_used: verdictData.revision_count || 0
  }
}];

// Match generated scripts to existing Google Docs by UGC_C{N} pattern
const data = $('Format Approved Scripts').first().json;
const docs = ($input.first().json.files || []).sort((a, b) => {
  const nA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  const nB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  return nA - nB;
});

const items = data.scripts.map((s, i) => ({
  json: {
    doc_id: docs[i] ? docs[i].id : null,
    doc_name: docs[i] ? docs[i].name : null,
    doc_content: s.doc_content,
    script_number: s.script_number
  }
}));

